1	/**
2	 * @file bsp_power.c
3	 * @brief 板级 GPIO 输出与 MPI2/SDIO 电源控制。
4	 *
5	 * BSP_GPIO_Set 供传感器、LCD、ETA9184 等直接控脚；
6	 * BSP_Power_Up/Down 管理深睡前后板级供电。
7	 *
8	 * SPDX-License-Identifier: Apache-2.0
9	 */
10	
11	#include "bsp_board.h"
12	
13	/**
14	 * @brief 将指定引脚配置为输出并写电平。
15	 * @param pin 引脚号（GPIO 组内索引）。
16	 * @param val 0 低，非 0 高。
17	 * @param is_porta 非 0 用 GPIO1（Port A），否则 GPIO2。
18	 */
19	void BSP_GPIO_Set(int pin, int val, int is_porta)
20	{
21	    GPIO_TypeDef *gpio = (is_porta) ? hwp_gpio1 : hwp_gpio2;
22	    GPIO_InitTypeDef GPIO_InitStruct;
23	
24	    GPIO_InitStruct.Mode = GPIO_MODE_OUTPUT;
25	    GPIO_InitStruct.Pin = pin;
26	    GPIO_InitStruct.Pull = GPIO_NOPULL;
27	    HAL_GPIO_Init(gpio, &GPIO_InitStruct);
28	
29	    HAL_GPIO_WritePin(gpio, pin, (GPIO_PinState)val);
30	}
31	
32	#define MPI2_POWER_PIN  (11) /**< MPI2 外设电源控制脚（Port A）。 */
33	
34	/** @brief 弱符号：深睡前关闭自定义外设电源。 */
35	__WEAK void BSP_PowerDownCustom(int coreid, bool is_deep_sleep)
36	{
37	    BSP_GPIO_Set(MPI2_POWER_PIN, 0, 1);
38	}
39	
40	/** @brief 弱符号：唤醒后打开自定义外设电源。 */
41	__WEAK void BSP_PowerUpCustom(bool is_deep_sleep)
42	{
43	    BSP_GPIO_Set(MPI2_POWER_PIN, 1, 1);
44	}
45	
46	/** @brief 板级上电：打开外设电源，深睡唤醒时恢复 PA21。 */
47	void BSP_Power_Up(bool is_deep_sleep)
48	{
49	    BSP_PowerUpCustom(is_deep_sleep);
50	#ifdef BSP_USING_BOARD_SF32LB52_LCD_52J_SD
51	    if (is_deep_sleep)
52	    {
53	        HAL_PIN_Set(PAD_PA21, GPIO_A21, PIN_NOPULL, 1);
54	    }
55	#endif /* BSP_USING_BOARD_SF32LB52_LCD_52J_SD */
56	}
57	
58	/** @brief 板级 IO 下电（深睡入口）。 */
59	void BSP_IO_Power_Down(int coreid, bool is_deep_sleep)
60	{
61	    BSP_PowerDownCustom(coreid, is_deep_sleep);
62	}
