6	 * 注册 /dev/buttons。只由板级线程 10 ms 读 GPIO，不上边沿中断、
7	 * 不挂 NuttX 软件 wdog。
8	 *
9	 * SPDX-License-Identifier: Apache-2.0
10	 */
11	
12	#include <nuttx/config.h>
13	
14	#include <stdbool.h>
15	#include <stdint.h>
16	#include <errno.h>
17	#include <unistd.h>
18	
19	#include <nuttx/input/buttons.h>
20	#include <nuttx/irq.h>
21	#include <nuttx/kthread.h>
22	#include <nuttx/sched.h>
23	#include <arch/irq.h>
