25	#include "sifli_gpio.h"
26	#include "sf32lb52_buttons.h"
27	
28	#ifdef CONFIG_INPUT_BUTTONS
29	
30	#define SF32LB52_BTN_CLICK_PIN   GET_PIN_2(hwp_gpio1, 33) /**< KEY2 PA33，bit0。 */
31	#define SF32LB52_BTN_SCROLL_PIN  GET_PIN_2(hwp_gpio1, 30) /**< KEY1 PA30，bit1。 */
32	#define SF32LB52_BTN_PWR_PIN     GET_PIN_2(hwp_gpio1, 34) /**< PWR PA34，bit2。 */
33	#define SF32LB52_BTN_CLICK_BIT   0  /**< KEY2 位掩码下标。 */
34	#define SF32LB52_BTN_SCROLL_BIT  1  /**< KEY1 位掩码下标。 */
35	#define SF32LB52_BTN_PWR_BIT     2  /**< PWR 位掩码下标。 */
36	#define SF32LB52_BTN_ACTIVE_HIGH 0  /**< KEY1/KEY2：0=上拉按下为低。 */
37	#define SF32LB52_BUTTON_POLL_MS  10 /**< 轮询周期（毫秒）。 */
38	#define SF32LB52_BUTTON_POLL_PRIO 50
39	#define SF32LB52_BUTTON_POLL_STACK 1536
40	
41	static uint8_t g_btn_poll_stack[SF32LB52_BUTTON_POLL_STACK]
42	    __attribute__((aligned(16)));
43	
44	/** @brief 按键 lower-half 私有状态。 */
45	struct sf32lb52_btnlower_s {
46	    struct btn_lowerhalf_s lower;
47	    btn_handler_t handler;       /**< NuttX 上报回调。 */
48	    FAR void *arg;               /**< 回调参数。 */
49	    volatile bool poll_enabled;  /**< 轮询线程是否采样。 */
50	    int poll_tid;                /**< 轮询线程 pid，0 表示未创建。 */
51	    btn_buttonset_t last_sample; /**< 上次采样位图。 */
52	};
53	
54	static btn_buttonset_t sf32lb52_btn_supported(
55	    FAR const struct btn_lowerhalf_s *lower);
56	static btn_buttonset_t sf32lb52_btn_buttons(
57	    FAR const struct btn_lowerhalf_s *lower);
58	static void sf32lb52_btn_enable(FAR const struct btn_lowerhalf_s *lower,
59	                                btn_buttonset_t press,
60	                                btn_buttonset_t release,
61	                                btn_handler_t handler,
62	                                FAR void *arg);
63	
64	/** 全局按键 lower-half 单例。 */
65	static struct sf32lb52_btnlower_s g_btnlower = {
66	    {
67	        sf32lb52_btn_supported,
68	        sf32lb52_btn_buttons,
69	        sf32lb52_btn_enable,
70	        NULL,
71	    },
72	    NULL,
73	    NULL,
74	    false,
75	    0,
76	    0,
77	};
78	
79	/** @brief 读取当前按键位图。 */
80	static btn_buttonset_t sf32lb52_button_readset(void)
81	{
82	    btn_buttonset_t set = 0;
83	    bool click = sifli_gpio_read(SF32LB52_BTN_CLICK_PIN);
84	    bool scroll = sifli_gpio_read(SF32LB52_BTN_SCROLL_PIN);
85	    bool pwr = sifli_gpio_read(SF32LB52_BTN_PWR_PIN);
86	
87	#if SF32LB52_BTN_ACTIVE_HIGH
88	    if (click) {
89	        set |= (1u << SF32LB52_BTN_CLICK_BIT);
90	    }
91	    if (scroll) {
92	        set |= (1u << SF32LB52_BTN_SCROLL_BIT);
93	    }
94	#else
95	    if (!click) {
96	        set |= (1u << SF32LB52_BTN_CLICK_BIT);
97	    }
98	    if (!scroll) {
99	        set |= (1u << SF32LB52_BTN_SCROLL_BIT);
100	    }
101	#endif
102	
103	    /* PWR_KEY_READ：按下为高。 */
104	    if (pwr) {
105	        set |= (1u << SF32LB52_BTN_PWR_BIT);
106	    }
107	
108	    return set;
109	}
110	
111	/** @brief 状态变化则通知 upper-half。 */
112	static void sf32lb52_button_notify(FAR struct sf32lb52_btnlower_s *priv)
113	{
114	    btn_buttonset_t sample;
115	    btn_handler_t handler;
116	    FAR void *arg;
117	    irqstate_t flags;
118	
119	    sample = sf32lb52_button_readset();
120	    if (sample == priv->last_sample) {
121	        return;
122	    }
123	
124	    /* handler 与 arg 必须在同一临界区里成对取出：enable 侧会在临界区内把两个
125	     * 一起置 NULL。以前是分两次裸读，中间被 enable 插进来就会用 NULL 调用
126	     * handler —— btn_interrupt 直接解引用 arg。回调在临界区外调用，避免带着
127	     * 关中断去跑上层代码。 */
128	    flags = up_irq_save();
129	    priv->last_sample = sample;
130	    handler = priv->handler;
131	    arg     = priv->arg;
132	    up_irq_restore(flags);
133	
134	    if (handler != NULL && arg != NULL) {
135	        handler(&priv->lower, arg);
136	    }
137	}
138	
139	/** @brief 板级轮询线程：只在线程上下文读键。 */
140	static int sf32lb52_button_poll_task(int argc, FAR char *argv[])
141	{
142	    FAR struct sf32lb52_btnlower_s *priv = &g_btnlower;
143	
144	    (void)argc;
145	    (void)argv;
146	
147	    for (;;) {
148	        if (priv->poll_enabled) {
149	            sf32lb52_button_notify(priv);
150	        }
151	
152	        usleep(SF32LB52_BUTTON_POLL_MS * 1000);
153	    }
154	
155	    return 0;
156	}
157	
158	/** @brief 返回支持的按键位掩码。 */
159	static btn_buttonset_t sf32lb52_btn_supported(
160	    FAR const struct btn_lowerhalf_s *lower)
161	{
162	    (void)lower;
163	    return (1u << SF32LB52_BTN_CLICK_BIT) |
164	           (1u << SF32LB52_BTN_SCROLL_BIT) |
165	           (1u << SF32LB52_BTN_PWR_BIT);
166	}
167	
168	/** @brief 返回当前按下的按键位。 */
169	static btn_buttonset_t sf32lb52_btn_buttons(
170	    FAR const struct btn_lowerhalf_s *lower)
171	{
172	    (void)lower;
173	    return sf32lb52_button_readset();
174	}
175	
176	/** @brief 使能/禁用轮询并挂接 handler。 */
177	static void sf32lb52_btn_enable(FAR const struct btn_lowerhalf_s *lower,
178	                                btn_buttonset_t press,
179	                                btn_buttonset_t release,
180	                                btn_handler_t handler,
181	                                FAR void *arg)
182	{
183	    FAR struct sf32lb52_btnlower_s *priv = (FAR struct sf32lb52_btnlower_s *)lower;
184	    btn_buttonset_t either = press | release;
185	    irqstate_t flags;
186	    int ret;
187	
188	    /* handler/arg 成对更新，与 sf32lb52_button_notify 的成对读取用同一临界区
189	     * 互斥；否则轮询线程可能取到"旧 handler + NULL arg"。 */
190	    if (either == 0 || handler == NULL) {
191	        flags = up_irq_save();
192	        priv->poll_enabled = false;
193	        priv->handler = NULL;
194	        priv->arg = NULL;
195	        up_irq_restore(flags);
196	        return;
197	    }
198	
199	    {
200	        btn_buttonset_t snap = sf32lb52_button_readset();
201	
202	        flags = up_irq_save();
203	        priv->handler = handler;
204	        priv->arg = arg;
205	        priv->last_sample = snap;
206	        priv->poll_enabled = true;
207	        up_irq_restore(flags);
208	    }
209	
210	    if (priv->poll_tid <= 0) {
211	        ret = kthread_create_with_stack("btn_poll",
212	                                        SF32LB52_BUTTON_POLL_PRIO,
213	                                        g_btn_poll_stack,
214	                                        sizeof(g_btn_poll_stack),
215	                                        sf32lb52_button_poll_task, NULL);
216	        if (ret > 0) {
217	            priv->poll_tid = ret;
218	        }
219	    }
220	}
