222	/**
223	 * @brief 初始化 PA30/PA33/PA34 并注册 /dev/buttons。
224	 * @param devname 字符设备路径。
225	 * @return 0 成功，负值为 btn_register 错误码。
226	 */
227	int sf32lb52_button_initialize(FAR const char *devname)
