150	#error "SDIO and MPI2 cannot be used at the same time, please disable one of them"
151	#endif
152	#endif
153	
154	#ifdef BSP_USING_SDIO
155	    HAL_PIN_Set(PAD_PA15, SD1_CMD, PIN_PULLUP, 1);
