169	    HAL_PIN_Set(PAD_PA14, MPI2_DIO2, PIN_PULLUP,   1);
170	    HAL_PIN_Set(PAD_PA17, MPI2_DIO3, PIN_PULLUP, 1);
171	#endif
172	    // UART1 - debug
173	    HAL_PIN_Set(PAD_PA18, USART1_RXD, PIN_PULLUP, 1);
174	    HAL_PIN_Set(PAD_PA19, USART1_TXD, PIN_PULLUP, 1);
175	
176	    /* UART2 - u-blox MAX-M10S-00B-01:
177	     * PA31 USART2_TXD -> GNSS_RX (module RX)
178	     * PA32 USART2_RXD <- GNSS_TX (module TX)
179	     * PA43 GNSS_PWR: module VCC (official low-power cut; host UART stays open) */
180	    HAL_PIN_Set(PAD_PA31, USART2_TXD, PIN_PULLUP, 1);
181	    HAL_PIN_Set(PAD_PA32, USART2_RXD, PIN_PULLUP, 1);
182	    /* GNSS_PWR PA43: idle off. Default active-low uses pull-up. */
183	#ifdef CONFIG_BOARD_L96_GNSS_PWR_ACTIVE_HIGH
184	    HAL_PIN_Set(PAD_PA43, GPIO_A43, PIN_PULLDOWN, 1);
