82	static void LCD_WriteReg(LCDC_HandleTypeDef *hlcdc, uint16_t LCD_Reg,
83	                         uint8_t *Parameters, uint32_t NbParameters)
84	{
85	  uint32_t cmd;
86	
87	  if ((REG_WRITE_RAM == LCD_Reg) || (REG_CONTINUE_WRITE_RAM == LCD_Reg))
88	    {
89	      cmd = (0x32u << 24) | ((uint32_t)LCD_Reg << 8);
90	    }
91	  else
92	    {
93	      cmd = (0x02u << 24) | ((uint32_t)LCD_Reg << 8);
94	    }
95	
96	  HAL_LCDC_WriteU32Reg(hlcdc, cmd, Parameters, NbParameters);
97	}
