1	/**
2	 * @file myvendor_bat_soc.h
3	 * @brief 单节锂电 SOC：软件 3.00 V～满电校准，开路电压分段表。
4	 *
5	 * NuttX 与 2SFBL 共用。电芯厂家截止 2.80 V，TPS63802 还能更低；产品 0%
6	 * 故意停在 3.00 V，留 200 mV 余量。满电点仍是 persist.battery.full_mv
7	 * （相对 4.20 V 参考曲线按比例拉伸）。
8	 *
9	 * SPDX-License-Identifier: Apache-2.0
10	 */
11	
12	#ifndef MYVENDOR_BAT_SOC_H
13	#define MYVENDOR_BAT_SOC_H
14	
15	#include <stdint.h>
16	
17	#ifdef __cplusplus
18	extern "C" {
19	#endif
20	
21	#define MYVENDOR_BAT_SOC_EMPTY_MV       3000  /**< 0%：软件截止（电芯 2.80 V）。 */
22	#define MYVENDOR_BAT_SOC_FULL_REF_MV    4200  /**< 曲线参考满电（未校准）。 */
23	#define MYVENDOR_BAT_SOC_CHG_DROP_MV      80  /**< 充电 IR/端电压抬升，仅用于 SOC。 */
24	#define MYVENDOR_BAT_SOC_STALE_FULL_MAX 4200  /**< 低于此的 KV 视为旧默认。 */
25	#define MYVENDOR_BAT_SOC_STALE_OBS_MIN  4300  /**< 本 ADC 已在 CV 附近。 */
26	
27	/**
28	 * @brief 轻载 OCV 点（毫伏 @ 4.20 V 满电）。中间段平、两端陡。
29	 */
30	typedef struct myvendor_bat_soc_pt_s
31	{
32	  uint16_t mv;
33	  uint8_t  pct;
34	} myvendor_bat_soc_pt_t;
35	
36	static const myvendor_bat_soc_pt_t MYVENDOR_BAT_SOC_CURVE[] =
37	{
38	  { 3000,   0 },
39	  { 3270,   5 },
40	  { 3500,  10 },
41	  { 3610,  20 },
42	  { 3690,  30 },
43	  { 3730,  40 },
44	  { 3780,  50 },
45	  { 3820,  60 },
46	  { 3870,  70 },
47	  { 3940,  80 },
48	  { 4030,  90 },
49	  { 4200, 100 },
50	};
51	
52	/**
53	 * @brief 在 3.00～4.20 V 参考曲线上查 SOC。
54	 */
55	static inline int myvendor_bat_soc_lookup(int ref_mv)
56	{
57	  const myvendor_bat_soc_pt_t *t = MYVENDOR_BAT_SOC_CURVE;
58	  const unsigned n =
59	      (unsigned)(sizeof(MYVENDOR_BAT_SOC_CURVE) / sizeof(t[0]));
60	  unsigned i;
61	  int mv0;
62	  int mv1;
63	  int p0;
64	  int p1;
65	
66	  if (ref_mv <= (int)t[0].mv)
67	    {
68	      return (int)t[0].pct;
69	    }
70	
71	  if (ref_mv >= (int)t[n - 1u].mv)
72	    {
73	      return (int)t[n - 1u].pct;
74	    }
75	
76	  for (i = 1; i < n; i++)
77	    {
78	      if (ref_mv > (int)t[i].mv)
79	        {
80	          continue;
81	        }
82	
83	      mv0 = (int)t[i - 1u].mv;
84	      mv1 = (int)t[i].mv;
85	      p0 = (int)t[i - 1u].pct;
86	      p1 = (int)t[i].pct;
87	      if (mv1 <= mv0)
88	        {
89	          return p1;
90	        }
91	
92	      return p0 + (int)(((int32_t)(ref_mv - mv0) * (p1 - p0)) / (mv1 - mv0));
93	    }
94	
95	  return 100;
96	}
97	
98	/**
99	 * @brief 把实测毫伏按当前满电校准映射到参考曲线再查表。
100	 */
101	static inline int myvendor_bat_soc_map_mv(int mv, int full)
102	{
103	  int ref_span;
104	  int span;
105	  int ref_mv;
106	
107	  if (mv < 0)
108	    {
109	      return -1;
110	    }
111	
112	  if (full <= MYVENDOR_BAT_SOC_EMPTY_MV)
113	    {
114	      full = MYVENDOR_BAT_SOC_FULL_REF_MV;
115	    }
116	
117	  if (mv <= MYVENDOR_BAT_SOC_EMPTY_MV)
118	    {
119	      return 0;
120	    }
121	
122	  if (mv >= full)
123	    {
124	      return 100;
125	    }
126	
127	  ref_span = MYVENDOR_BAT_SOC_FULL_REF_MV - MYVENDOR_BAT_SOC_EMPTY_MV;
128	  span = full - MYVENDOR_BAT_SOC_EMPTY_MV;
129	  if (span <= 0)
130	    {
131	      return 100;
132	    }
133	
134	  ref_mv = MYVENDOR_BAT_SOC_EMPTY_MV +
135	           (int)(((int32_t)(mv - MYVENDOR_BAT_SOC_EMPTY_MV) * ref_span) /
136	                 span);
137	  return myvendor_bat_soc_lookup(ref_mv);
138	}
139	
140	/**
141	 * @brief 产品 SOC。充电且未充满时扣压降；满电校准仍用原始毫伏。
142	 *
143	 * @param charging 非 0：ETA9184 充电中。
144	 * @param charge_full 非 0：充满 IO（不扣压降）。
145	 */
146	static inline int myvendor_bat_soc_pct(int mv, int full, int charging,
147	                                       int charge_full)
148	{
149	  int soc_mv = mv;
150	
151	  if (charging && !charge_full && soc_mv >= 0)
152	    {
153	      soc_mv -= MYVENDOR_BAT_SOC_CHG_DROP_MV;
154	      if (soc_mv < MYVENDOR_BAT_SOC_EMPTY_MV)
155	        {
156	          soc_mv = MYVENDOR_BAT_SOC_EMPTY_MV;
157	        }
158	    }
159	
160	  return myvendor_bat_soc_map_mv(soc_mv, full);
161	}
162	
163	#ifdef __cplusplus
164	}
165	#endif
166	
167	#endif /* MYVENDOR_BAT_SOC_H */
