842	/**
843	 * @brief `ctl boot` 读启动槽位；`ctl boot fw|main|factory` 写 persist.boot.target。
844	 *
845	 * 2SFBL 的选择顺序是 `persist.boot.target` → `/fw` → `main` → `factory`。
846	 * 设备出厂时 `persist.boot.target` 是 `fw`（SD 上的 OTA 文件），所以
847	 * **`flash` 写完 main 分区之后如果没把 target 切到 `main`，跑的还是 `/fw`
848	 * 里那个旧镜像** —— 现场踩过：`flash` 明明成功、`build_date` 却不变。
849	 *
850	 * 写入**下一次开机**才生效（本命令不复位）：`ctl off` 或 NSH `reboot` 都行。
851	 * "现在实际跑的是哪个槽 / 哪一版"看 `sys` 输出里的 `slot` 那行。
852	 */
853	static int cmd_boot(int argc, char *argv[])
854	{
855	  char cur[MYVENDOR_DEVCTL_BOOT_TARGET_MAX];
856	
857	  if (argc < 2)
858	    {
859	      if (myvendor_devctl_boot_target_get(cur, sizeof(cur)))
860	        {
861	          printf("ctl boot target=%s\n", cur);
862	        }
863	      else
864	        {
865	          printf("ctl boot target=(unset; 2SFBL 走默认 /fw > main > factory)\n");
866	        }
867	
868	      printf("ctl boot running: see `sys` (slot 行)\n");
869	      return 0;
870	    }
871	
872	  /* 校验在 setter 里（它只认 fw|main|factory，不认就回 -EINVAL）——
873	   * 写错名字的后果是 2SFBL 认不出、退回默认顺序，用户会以为"改了没生效"，
874	   * 所以宁可在这里拒掉而不是把任意字符串落盘。 */
875	  if (myvendor_devctl_boot_target_set(argv[1]) < 0)
876	    {
877	      fprintf(stderr, "ctl boot: use fw|main|factory\n");
878	      return EXIT_FAILURE;
879	    }
880	
881	  printf("ctl boot %s (next boot; then `sys` 的 slot 行核对)\n", argv[1]);
882	  return 0;
883	}
