219	static bool helm_idle_wall_now(struct tm *out)
220	{
221	    time_t now = time(NULL);
222	    time_t local;
223	    int16_t tz;
224	
225	    if (out == NULL || now < 1704067200) {
226	        return false;
227	    }
228	
229	    tz = myvendor_devctl_tz_min_get();
230	    local = now + (time_t)tz * 60;
231	    if (gmtime_r(&local, out) == NULL) {
232	        return false;
233	    }
234	
235	    return true;
236	}
