362	static bool helm_idle_moving(void)
363	{
364	    myvendor_sys_vec3_t raw;
365	    myvendor_sys_vec3_t filt;
366	    myvendor_sys_vec3_t gyro;
367	    float dx;
368	    float dy;
369	    float dz;
370	    float mag2;
371	    const float ath2 = HELM_IDLE_ACCEL_TH * HELM_IDLE_ACCEL_TH;
372	    const float gth2 = HELM_IDLE_GYRO_TH * HELM_IDLE_GYRO_TH;
373	
374	    myvendor_board_sensor_accel_get(&raw);
375	    myvendor_board_sensor_accel_filt_get(&filt);
376	    myvendor_board_sensor_gyro_get(&gyro);
377	    if (!raw.valid) {
378	        /* IMU 无效时不要睡，避免一直黑屏。 */
379	        return true;
380	    }
381	
382	    dx = raw.x - filt.x;
383	    dy = raw.y - filt.y;
384	    dz = raw.z - filt.z;
385	    mag2 = dx * dx + dy * dy + dz * dz;
386	    if (mag2 > ath2) {
387	        return true;
388	    }
389	
390	    if (gyro.valid) {
391	        mag2 = gyro.x * gyro.x + gyro.y * gyro.y + gyro.z * gyro.z;
392	        if (mag2 > gth2) {
393	            return true;
394	        }
395	    }
396	
397	    return false;
398	}
