518	void helm_idle_tick(void)
519	{
520	    uint32_t now = lv_tick_get();
521	
522	    if (myvendor_is_factory() || helm_pwr_is_offing()) {
523	        return;
524	    }
525	
526	    if (s_sleep) {
527	        helm_idle_overlay_refresh();
528	        if (helm_pwr_dialog_open()) {
529	            helm_idle_wake();
530	            return;
531	        }
532	
533	        if (helm_idle_moving()) {
534	            helm_idle_wake();
535	            return;
536	        }
537	
538	        if (lv_tick_elaps(s_enter_t0) >= HELM_IDLE_OFF_MS &&
539	            myvendor_sys_power_state() != MYVENDOR_SYS_PWR_CHARGING) {
540	            syslog(LOG_INFO, "helm: idle 1h still, poweroff");
541	            helm_pwr_exec_as("静止超时");
542	        }
543	
544	        return;
545	    }
546	
547	    if (s_stay) {
548	        s_still_t0 = now;
549	        return;
550	    }
551	
552	    if (!s_boot_armed) {
553	        s_boot_armed = true;
554	        s_boot_t0 = now;
555	        s_still_t0 = now;
556	        return;
557	    }
558	
559	    if (lv_tick_elaps(s_boot_t0) < HELM_IDLE_BOOT_MS) {
560	        s_still_t0 = now;
561	        return;
562	    }
563	
564	    if (helm_pwr_dialog_open()) {
565	        s_still_t0 = now;
566	        return;
567	    }
568	
569	    if (helm_idle_moving()) {
570	        s_still_t0 = now;
571	        return;
572	    }
573	
574	    if (lv_tick_elaps(s_still_t0) >= HELM_IDLE_STILL_MS) {
575	        helm_idle_enter();
576	    }
577	}
