1385	/**
1386	 * @brief zblue 连接：仅 Peripheral（手机）收紧 7.5 ms / PHY / DLE。
1387	 *
1388	 * 传感器（central）保持 BT_LE_CONN_PARAM_DEFAULT。7.5 ms / 1 s + PHY+DLE
1389	 * 会和 Android 的 45 ms 更新打架（HCI 0x16），发现前就断链。
1390	 */
1391	static void le_connected(struct bt_conn *conn, uint8_t err)
1392	{
1393	  struct bt_conn_info info;
1394	
1395	  if (err != 0 || bt_conn_get_info(conn, &info) != 0 ||
1396	      info.type != BT_CONN_TYPE_LE)
1397	    {
1398	      return;
1399	    }
1400	
1401	  if (info.role == BT_CONN_ROLE_PERIPHERAL)
1402	    {
1403	      int ret;
1404	
1405	      /* **先抓原始 InitA/RPA。**
1406	       *
1407	       * `info.le.remote` 是连接建立时的对端地址，`bt_lookup_id_addr()`
1408	       * 不会改写它；`bt_conn_get_dst()` / GATTS 回调拿到的则是解析后的
1409	       * 身份地址。定向广播的 TargetA 必须用这里的 RPA。
1410	       * 只暂存真正的 RPA；身份核对和缓存提升由 companion 线程完成。 */
1411	      pthread_mutex_lock(&g_rpa_lock);
1412	      g_pending_peer_rpa_valid = false;
1413	      g_pending_peer_conn = NULL;
1414	      g_pending_peer_secure = false;
1415	      if (info.le.remote != NULL && bt_addr_le_is_rpa(info.le.remote))
1416	        {
1417	          memcpy(g_pending_peer_rpa, info.le.remote->a.val,
1418	                 sizeof(g_pending_peer_rpa));
1419	          g_pending_peer_rpa_ms = mono_ms();
1420	          g_pending_peer_rpa_valid = true;
1421	          g_pending_peer_conn = conn;
1422	        }
1423	      pthread_mutex_unlock(&g_rpa_lock);
1424	
1425	      /* **控制器没就绪就别发这一族命令。**
1426	       *
1427	       * 连接刚建立时下发的 PM/参数命令（param update / PHY / data len）正是
1428	       * 被 NOT_READY 控制器吞掉的那一族：命令发出去没有 Command Status，
1429	       * `txop` 一直挂着 → diag 判 `cmdsilent` → 复位适配器 → 把刚连上的链路
1430	       * 踢掉（现场：手机连上 4.4 s 内无任何 HCI 收发，`status=2`）。
1431	       *
1432	       * 跳过它们的代价≈0：实测即使请求成功，间隔最后也会回到 30 ms
1433	       * （`conn_upd#2 itv=24(30.00 ms)`），所以**不发不吃亏**，而发了会喂出
1434	       * 一串假 cmdsilent。 */
1435	      if (!adapter_is_usable())
1436	        {
1437	          static uint32_t last_log_ms;
1438	
1439	          if (last_log_ms == 0 ||
1440	              myvendor_mono_elapsed_ms(mono_ms(), last_log_ms) >= 10000u)
1441	            {
1442	              last_log_ms = mono_ms();
1443	              syslog(LOG_WARNING,
1444	                     "ble_companion: PM tuning skipped, adapter not ready\n");
1445	            }
1446	
1447	          return;
1448	        }
1449	
1450	      /** 参数取**厂商 SDK 的"高性能档"原值**，不要再自己发明。
1451	       *
1452	       *  `ble_connection_manager.h` 里三档是
1453	       *    高性能 12/12（15 ms）/ latency 0 / timeout 600（6 s）
1454	       *    均衡   24~40（30~50 ms）/ 0 / 600
1455	       *    低功耗 80~100（100~125 ms）/ 2 / 600
1456	       *  并注明了"iOS 支持的最大监督超时是 6 s"。厂商的
1457	       *  `file_transfer` 例程也是在传输期间强制切到高性能档。
1458	       *
1459	       *  以前这里要的是 `6/6/0/400`：**间隔 7.5 ms 是 BLE 规定的下限**，
1460	       *  手机基本不会给（本文件自己的注释就记着"间隔最后也会回到 30 ms"），
1461	       *  而 **4 s 监督超时比厂商的 6 s 短三分之一** —— 在一块"一张射频同时
1462	       *  跑手机广播 + 传感器扫描"的板子上，缺的正是这两秒余量。
1463	       *
1464	       *  自证伪：若日志里 `le interval=` 长期停在 15 ms 且丢链变多，说明本档
1465	       *  对这台手机偏激进 ⇒ 改投均衡档（24~40 / 0 / 600）。
1466	       */
1467	      ret = bt_conn_le_param_update(conn, BT_LE_CONN_PARAM(12, 12, 0, 600));
1468	      LOGD("le interval 15 ms ret=%d", ret);
1469	      (void)ret;
