134	  if (strcmp(s, "pwr") == 0 || strcmp(s, "pa27") == 0 ||
135	      strcmp(s, "pwr_md") == 0)
136	    {
137	      *mask = (1u << IOWRITE_PIN_PWR);
138	      return 0;
139	    }
140	
141	  if (strcmp(s, "gnss") == 0 || strcmp(s, "pa43") == 0 ||
