/**
 * @brief 有符号定点数，不用 %f（sys 任务栈上 dtoa 会打穿 NSH）。
 *
 * @param v      值。
 * @param scale  10=一位小数，100=两位。
 */
static void sys_print_fixed(float v, unsigned scale)
{
  int neg;
  int scaled;
  unsigned mag;
  unsigned frac;

  if (scale != 10u && scale != 100u)
    {
      scale = 100u;
    }

  neg = (v < 0.0f);
  if (neg)
    {
      v = -v;
    }

  scaled = (int)(v * (float)scale + 0.5f);
  if (scaled < 0)
    {
      scaled = 0;
    }

  mag = (unsigned)scaled;
  frac = mag % scale;
  mag /= scale;
  if (neg && (mag != 0 || frac != 0))
    {
      putchar('-');
    }

  if (scale == 100u)
    {
      printf("%u.%02u", mag, frac);
    }
  else
    {
      printf("%u.%u", mag, frac);
    }
}

