/****************************************************************************
 * Name: bmi270_set_normal_imu
 *
 * Description:
 *   set bmi270 to normal IMU mode.
 *
 ****************************************************************************/

void bmi270_set_normal_imu(FAR struct bmi270_dev_s *priv)
{
  /* Enable acquisition of acc and gyro */

  bmi270_putreg8(priv, BMI270_PWR_CTRL, PWRCTRL_GYR_EN | PWRCTRL_ACC_EN);
  nxsig_usleep(30000);

  /* Set accel and gyro output data rate */

  bmi270_putreg8(priv, BMI270_ACC_CONF,
                 ACCEL_NORMAL_AVG4 | ACCEL_ODR_100HZ);
  bmi270_putreg8(priv, BMI270_GYR_CONF,
                 GYRO_NORMAL_MODE | GYRO_ODR_100HZ);

  /* Disable the adv_power_save bit */

  bmi270_putreg8(priv, BMI270_PWR_CONF, PWRCONF_FSW_ON);
}

