static uint8_t clamp_bl(int v)
{
  uint8_t maxp = BSP_LCD_BL_GetMaxPct();

  if (v < 0)
    {
      return 0;
    }

  if (maxp > 0 && v > (int)maxp)
    {
      return maxp;
    }

  if (v > 100)
    {
