    if (!g_ready)
    {
        return;
    }
    if (pct > LCD_BL_MAX_BRIGHTNESS_PCT)
    {
        pct = LCD_BL_MAX_BRIGHTNESS_PCT;
    }

    if (g_bl_pwm.Instance == NULL)
    {
        memset(&g_bl_pwm, 0, sizeof(g_bl_pwm));
        g_bl_pwm.Instance = GPTIM1;
        g_bl_pwm.core = CORE_ID_HCPU;
