    HAL_RCC_EnableModule(RCC_MOD_GPTIM1);
    timclk = 24000000u;
    ticks = (uint64_t)timclk / (uint64_t)LCD_BL_PWM_FREQ_HZ;
    if (ticks == 0)
    {
        ticks = 1;
    }
    prescaler = (uint32_t)((ticks + 65535ULL - 1ULL) / 65535ULL);
    if (prescaler == 0)
    {
        prescaler = 1;
    }
    period = (uint32_t)(ticks / prescaler);
    if (period == 0)
    {
        period = 1;
    }
    else if (period > 65535)
